import{_ as o,c as a,o as i,ae as t}from"./chunks/framework.DNEoaTf_.js";const c=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/troubleshooting.md","filePath":"en/guide/troubleshooting.md"}'),l={name:"en/guide/troubleshooting.md"};function n(s,e,r,h,u,d){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="thumbnails-not-displaying" tabindex="-1">Thumbnails Not Displaying <a class="header-anchor" href="#thumbnails-not-displaying" aria-label="Permalink to &quot;Thumbnails Not Displaying&quot;">​</a></h2><h3 id="causes-and-solutions" tabindex="-1">Causes and Solutions <a class="header-anchor" href="#causes-and-solutions" aria-label="Permalink to &quot;Causes and Solutions&quot;">​</a></h3><h4 id="not-on-a-youtube-video-page" tabindex="-1">Not on a YouTube Video Page <a class="header-anchor" href="#not-on-a-youtube-video-page" aria-label="Permalink to &quot;Not on a YouTube Video Page&quot;">​</a></h4><ul><li>The extension only works on YouTube video playback pages</li><li>It will not work on the homepage or channel pages</li></ul><h4 id="video-not-loaded" tabindex="-1">Video Not Loaded <a class="header-anchor" href="#video-not-loaded" aria-label="Permalink to &quot;Video Not Loaded&quot;">​</a></h4><ul><li>Wait for the page to fully load</li><li>Try refreshing the page</li></ul><h4 id="insufficient-extension-permissions" tabindex="-1">Insufficient Extension Permissions <a class="header-anchor" href="#insufficient-extension-permissions" aria-label="Permalink to &quot;Insufficient Extension Permissions&quot;">​</a></h4><ol><li>Open <code>chrome://extensions/</code> (Chrome) or <code>about:addons</code> (Firefox)</li><li>Find YouTube Watch Thumbnails</li><li>Click <strong>Details</strong></li><li>Verify all permissions are enabled</li></ol><h2 id="some-thumbnails-not-showing" tabindex="-1">Some Thumbnails Not Showing <a class="header-anchor" href="#some-thumbnails-not-showing" aria-label="Permalink to &quot;Some Thumbnails Not Showing&quot;">​</a></h2><h3 id="maxresdefault-not-available" tabindex="-1">maxresdefault Not Available <a class="header-anchor" href="#maxresdefault-not-available" aria-label="Permalink to &quot;maxresdefault Not Available&quot;">​</a></h3><ul><li>maxresdefault (maximum quality) is not available for all videos</li><li>YouTube may not generate high-resolution thumbnails for some videos</li><li>Use lower resolution thumbnails (hqdefault, etc.)</li></ul><h3 id="webp-format-not-available" tabindex="-1">WebP Format Not Available <a class="header-anchor" href="#webp-format-not-available" aria-label="Permalink to &quot;WebP Format Not Available&quot;">​</a></h3><ul><li>Some videos may not provide WebP format thumbnails</li><li>Use JPG format instead</li></ul><h2 id="popup-not-opening" tabindex="-1">Popup Not Opening <a class="header-anchor" href="#popup-not-opening" aria-label="Permalink to &quot;Popup Not Opening&quot;">​</a></h2><h3 id="things-to-check" tabindex="-1">Things to Check <a class="header-anchor" href="#things-to-check" aria-label="Permalink to &quot;Things to Check&quot;">​</a></h3><ul><li>Verify you&#39;re playing a video on a YouTube video page</li><li>Try restarting your browser</li><li>Disable and then re-enable the extension</li></ul><h2 id="cannot-download" tabindex="-1">Cannot Download <a class="header-anchor" href="#cannot-download" aria-label="Permalink to &quot;Cannot Download&quot;">​</a></h2><h3 id="unable-to-save-image" tabindex="-1">Unable to Save Image <a class="header-anchor" href="#unable-to-save-image" aria-label="Permalink to &quot;Unable to Save Image&quot;">​</a></h3><ul><li>Select <strong>Save image as</strong> from the right-click menu</li><li>Or, click the image to open in a new tab and save from there</li><li>Check if downloads are allowed in your browser settings</li></ul><h2 id="not-working-with-youtube-shorts" tabindex="-1">Not Working with YouTube Shorts <a class="header-anchor" href="#not-working-with-youtube-shorts" aria-label="Permalink to &quot;Not Working with YouTube Shorts&quot;">​</a></h2><h3 id="solutions" tabindex="-1">Solutions <a class="header-anchor" href="#solutions" aria-label="Permalink to &quot;Solutions&quot;">​</a></h3><ul><li>Wait for the Short to fully load on the Shorts page</li><li>Try refreshing the page</li><li>Try the same operation as regular videos (click toolbar icon)</li></ul><h2 id="still-not-resolved" tabindex="-1">Still Not Resolved? <a class="header-anchor" href="#still-not-resolved" aria-label="Permalink to &quot;Still Not Resolved?&quot;">​</a></h2><p>Try these methods:</p><ol><li><strong>Restart Extension</strong>: Disable and then re-enable the extension</li><li><strong>Restart Browser</strong>: Completely close and reopen your browser</li><li><strong>Reinstall Extension</strong>: Uninstall and reinstall the latest version</li><li><strong>Clear Browser Cache</strong>: Delete cache from browser settings</li></ol><div class="tip custom-block"><p class="custom-block-title">Support</p><p>If the above doesn&#39;t resolve your issue, please report it on <a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a>. Include:</p><ul><li>Browser and version you&#39;re using</li><li>URL of the video where the issue occurred</li><li>Error message (if any)</li></ul></div>',27)])])}const m=o(l,[["render",n]]);export{c as __pageData,m as default};
